<polyline points="90,228 96.3333,224.404 102.667,220.931 109,217.579 115.333,214.349 121.667,211.241 128,208.255 134.333,205.39 140.667,202.648 147,200.027 153.333,197.529 159.667,195.152 166,192.897 172.333,190.764 178.667,188.753 185,186.864 191.333,185.096 197.667,183.451 204,181.927 210.333,180.526 216.667,179.246 223,178.088 229.333,177.052 235.667,176.138 242,175.346 248.333,174.675 254.667,174.127 261,173.7 267.333,173.395 273.667,173.213 280,173.152 286.333,173.213 292.667,173.395 299,173.7 305.333,174.127 311.667,174.675 318,175.346 324.333,176.138 330.667,177.052 337,178.088 343.333,179.246 349.667,180.526 356,181.927 362.333,183.451 368.667,185.096 375,186.864 381.333,188.753 387.667,190.764 394,192.897 400.333,195.152 406.667,197.529 413,200.027 419.333,202.648 425.667,205.39 432,208.255 438.333,211.241 444.667,214.349 451,217.579 457.333,220.931 463.667,224.404 470,228" fill="none" stroke="#a8641a" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/>
